you could try running something like this, which exercises the local logic of the old and new quantize methods and checks that they output roughly similar values (some drift is expected because one uses wall clock and the other uses monotonic clock)

```go
package main

import (
	"fmt"
	"math"
	"runtime"
	"time"
)

func main() {
	fmt.Println("Testing old vs new quantize methods, ctrl+c to stop...")
	swg := &sampleAndWaterMarkObserverGenerator{
		samplePeriod: time.Millisecond,
		t0:           time.Now(),
	}
	oldBaseline := swg.oldQuantize(swg.t0)
	newBaseline := swg.newQuantize(swg.t0)
	// set up a few goroutines per CPU
	for i := 0; i < 4*runtime.NumCPU(); i++ {
		go func() {
			for {
				when := time.Now()
				oldDelta := swg.oldQuantize(when) - oldBaseline
				newDelta := swg.newQuantize(when) - newBaseline
				// if the results are more than a second off, print
				if math.Abs(float64(oldDelta-newDelta)) > 1000 {
					fmt.Printf("%v to %v: old=%v, new=%v\n", swg.t0, when, oldDelta, newDelta)
				}
			}
		}()
	}
	select {}
}

type sampleAndWaterMarkObserverGenerator struct {
	t0           time.Time
	samplePeriod time.Duration
}

func (swg *sampleAndWaterMarkObserverGenerator) oldQuantize(when time.Time) int64 {
	return when.UnixNano() / int64(swg.samplePeriod)
}
func (swg *sampleAndWaterMarkObserverGenerator) newQuantize(when time.Time) int64 {
	return int64(when.Sub(swg.t0) / swg.samplePeriod)
}
```

